nodeSources.deliver:
# Deliver the routine's answer, Markdown or HTML from its template, to the owner only, by email or as a Teams
# message to themselves.
import html
import json
from urllib.parse import urlparse

import bs4
import markdown
from semoss import Insight

FONT = "Arial, Helvetica, sans-serif"
TEAMS_LIMIT = 24000
# Links the agent writes can come from mail it read; keep only Microsoft 365 ones.
LINK_HOSTS = ("outlook.office.com", "outlook.office365.com", "outlook.live.com", "teams.microsoft.com",
              "sharepoint.com", "onedrive.live.com", "office.com")
STYLES = {
    "h1": "margin:18px 0 8px; font-size:20px; font-weight:bold;",
    "h2": "margin:18px 0 8px; font-size:17px; font-weight:bold;",
    "h3": "margin:14px 0 6px; font-size:15px; font-weight:bold;",
    "p": "margin:0 0 10px;",
    "ul": "margin:0 0 12px; padding:0 0 0 20px;",
    "ol": "margin:0 0 12px; padding:0 0 0 20px;",
    "li": "margin:0 0 6px;",
    "table": "border-collapse:collapse; margin:0 0 12px;",
    "th": "padding:6px 8px; border:1px solid #D0D0CE; text-align:left;",
    "td": "padding:6px 8px; border:1px solid #D0D0CE;",
}


# Only simple email-safe markup survives; anything else is unwrapped to its text, or dropped with its content.
TAGS = {"a", "b", "blockquote", "br", "caption", "code", "col", "colgroup", "div", "em", "h1", "h2", "h3", "h4",
        "hr", "i", "li", "ol", "p", "pre", "s", "small", "span", "strong", "sub", "sup", "table", "tbody", "td",
        "tfoot", "th", "thead", "tr", "u", "ul"}
DROP = {"script", "style", "head", "title", "iframe", "object", "embed", "form", "input", "button", "select",
        "textarea", "link", "meta", "base", "img", "svg", "math", "video", "audio", "source", "noscript", "template"}
ATTRS = {"style", "href", "colspan", "rowspan", "align", "valign", "width", "border", "cellpadding", "cellspacing",
         "bgcolor"}
UNSAFE_CSS = ("url(", "expression", "@import", "behavior", "javascript:", "position", "\\")


def _sanitize(soup):
    for comment in soup.find_all(string=lambda text: isinstance(text, bs4.Comment)):
        comment.extract()
    for tag in soup.find_all(list(DROP)):
        tag.decompose()
    for tag in soup.find_all(True):
        if tag.name not in TAGS:
            tag.unwrap()
            continue
        for attr in list(tag.attrs):
            value = str(tag.attrs[attr]).lower()
            if attr not in ATTRS or (attr == "style" and any(bad in value for bad in UNSAFE_CSS)):
                del tag.attrs[attr]
    for link in soup.find_all("a"):
        if not _allowed(link.get("href")):
            link.unwrap()
    for tag in soup.find_all(list(STYLES)):
        if not tag.get("style"):
            tag["style"] = STYLES[tag.name]
    return soup


def _allowed(href):
    try:
        url = urlparse(str(href or ""))
    except ValueError:
        return False
    host = (url.hostname or "").lower()
    return url.scheme == "https" and any(host == h or host.endswith("." + h) for h in LINK_HOSTS)


def _pixel_value(name, value):
    # Pixel decodes \u escapes, so model text can never open an <encode> tag in the Pixel.
    return name + "=[" + json.dumps(value).replace("<", "\\u003c") + "]"


def _run(pixel, what):
    ret = Insight().run_pixel(pixel, raw=True)
    last = ret[0]["pixelReturn"][-1]
    if "ERROR" in str(last.get("operationType")):
        raise RuntimeError(what + " failed: " + str(last.get("output")))


def run(scope):
    recipient = str(scope.get("owner_email") or "").strip()
    delivery = str(scope.get("delivery") or "email").strip().lower()
    name = str(scope.get("routine_name") or "Routine").strip()
    # Markdown keeps HTML blocks as they are, so a filled template passes through; the allowlist then decides
    # what of it reaches the message.
    rendered = markdown.markdown(str(scope["answer"]), extensions=["tables"])
    content = str(_sanitize(bs4.BeautifulSoup(rendered, "html.parser"))).strip()
    if delivery == "none":
        return {"sent": False, "to": None, "html": content}
    if not recipient:
        raise ValueError("There is no owner address to deliver to.")
    if delivery == "teams":
        message = "<p><strong>" + html.escape(name) + "</strong></p>" + content
        if len(message) > TEAMS_LIMIT:
            message = message[:TEAMS_LIMIT] + "<p>(Shortened. Open Routines for the full result.)</p>"
        _run("MicrosoftTeamsSendChatMessage(" + ", ".join([
            _pixel_value("recipients", [recipient]),
            _pixel_value("message", message),
            _pixel_value("html", True),
        ]) + ");", "Sending the Teams message")
    else:
        body = ('<div style="font-family:' + FONT + '; font-size:14px; line-height:1.5; color:#000000;">'
                + content + '<p style="margin-top:18px; font-size:12px; color:#53565A;">Sent to you by your routine "'
                + html.escape(name) + '". Change or pause it in Routines.</p></div>')
        _run("MicrosoftOutlookSendMail(" + ", ".join([
            _pixel_value("to", [recipient]),
            _pixel_value("subject", name),
            _pixel_value("body", body),
            _pixel_value("html", True),
        ]) + ");", "Sending the email")
    return {"sent": True, "to": recipient, "html": content}
